CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS disciplines (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,description text,semester text NOT NULL,color text NOT NULL DEFAULT '#5eead4',status text NOT NULL DEFAULT 'ATIVA',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS topics (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),discipline_id uuid NOT NULL REFERENCES disciplines(id) ON DELETE CASCADE,name text NOT NULL,description text,status text NOT NULL DEFAULT 'NAO_ESTUDADO',mastery integer NOT NULL DEFAULT 0 CHECK (mastery BETWEEN 0 AND 100),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS materials (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),discipline_id uuid NOT NULL REFERENCES disciplines(id) ON DELETE CASCADE,topic_id uuid REFERENCES topics(id) ON DELETE SET NULL,title text NOT NULL,type text NOT NULL,content text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS material_chunks (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),material_id uuid NOT NULL REFERENCES materials(id) ON DELETE CASCADE,discipline_id uuid NOT NULL REFERENCES disciplines(id) ON DELETE CASCADE,topic_id uuid REFERENCES topics(id) ON DELETE SET NULL,position integer NOT NULL,content text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS material_chunks_scope_idx ON material_chunks(discipline_id,topic_id);
CREATE TABLE IF NOT EXISTS difficulties (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),discipline_id uuid NOT NULL REFERENCES disciplines(id) ON DELETE CASCADE,topic_id uuid NOT NULL REFERENCES topics(id) ON DELETE CASCADE,original_report text NOT NULL,last_report text NOT NULL,occurrences integer NOT NULL DEFAULT 1,level text NOT NULL DEFAULT 'NAO_ENTENDI',status text NOT NULL DEFAULT 'ABERTA',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS difficulties_topic_idx ON difficulties(topic_id,status);
CREATE TABLE IF NOT EXISTS tutor_messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),difficulty_id uuid NOT NULL REFERENCES difficulties(id) ON DELETE CASCADE,role text NOT NULL,mode text NOT NULL DEFAULT 'DIAGNOSTICAR',content text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS study_sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),discipline_id uuid REFERENCES disciplines(id) ON DELETE SET NULL,topic_id uuid REFERENCES topics(id) ON DELETE SET NULL,activity_type text NOT NULL,duration_minutes integer,result text,note text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS quizzes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),discipline_id uuid NOT NULL REFERENCES disciplines(id) ON DELETE CASCADE,topic_id uuid REFERENCES topics(id) ON DELETE SET NULL,material_id uuid REFERENCES materials(id) ON DELETE SET NULL,title text NOT NULL,question_count integer NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS quiz_questions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),quiz_id uuid NOT NULL REFERENCES quizzes(id) ON DELETE CASCADE,topic_id uuid REFERENCES topics(id) ON DELETE SET NULL,prompt text NOT NULL,type text NOT NULL,options jsonb NOT NULL,correct_answer text NOT NULL,explanation text NOT NULL);
CREATE TABLE IF NOT EXISTS quiz_attempts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),quiz_id uuid NOT NULL REFERENCES quizzes(id) ON DELETE CASCADE,score integer NOT NULL,correct_count integer NOT NULL,total integer NOT NULL,answers jsonb NOT NULL,weaknesses jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS reviews (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),discipline_id uuid NOT NULL REFERENCES disciplines(id) ON DELETE CASCADE,topic_id uuid NOT NULL REFERENCES topics(id) ON DELETE CASCADE,scheduled_for date NOT NULL,status text NOT NULL DEFAULT 'PENDENTE',completed_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS reviews_due_idx ON reviews(status,scheduled_for);
CREATE TABLE IF NOT EXISTS exams (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),discipline_id uuid NOT NULL REFERENCES disciplines(id) ON DELETE CASCADE,name text NOT NULL,exam_date date NOT NULL,notes text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS exam_topics (exam_id uuid NOT NULL REFERENCES exams(id) ON DELETE CASCADE,topic_id uuid NOT NULL REFERENCES topics(id) ON DELETE CASCADE,PRIMARY KEY(exam_id,topic_id));
